/* a soft wobbly blob: n bumps, inner radius k*r */
function wobblePath(cx, cy, r, n, k, rot) {
  const P = [];
  for (let i = 0; i < n * 2; i++) { const a = (rot || 0) + i * Math.PI / n, rr = r * (i % 2 ? k : 1); P.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr]); }
  const mid = (a, b) => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
  const s0 = mid(P[P.length - 1], P[0]);
  let s = `M${pt(s0[0], s0[1])}`;
  for (let i = 0; i < P.length; i++) { const q = mid(P[i], P[(i + 1) % P.length]); s += `Q${pt(P[i][0], P[i][1])} ${pt(q[0], q[1])}`; }
  return s + 'Z';
}
