/* Tower experience a meal gives the pet that eats it: food levels pets up outside combat */
const FOOD_DXP = { berries: 8, fish: 12, cookie: 4, cake: 24, sunberry: 16, carrot: 28, pumpkin: 55, starfruit: 190, soda: 3, tea: 5 };
/* ambrosia and honeycomb scale with the level (a third or a half of what the next level needs, rounded up); a grand feast
   is all the experience of the next twenty levels, so the pet keeps its progress into the level it reaches */
const foodXP = (k, p) => {
  const s = SNACKS[k], q = p || st, L = (q && q.dlv) || 1;
  if (s && s.lvAdd) { let x = 0; for (let i = 0; i < s.lvAdd && L + i < DLV_MAX; i++) x += dunXpNeed(L + i); return x; }
  return s && s.lvFrac ? Math.ceil(dunXpNeed(L) * s.lvFrac) : (FOOD_DXP[k] || 5);
};
/* what a food does, in a few words for its button */
function foodEffect(k, p) { const s = SNACKS[k]; if (!s) return ''; if (s.bondLv) return `+${s.bondLv} bond levels`; if (s.lvAdd) return `+${s.lvAdd} pet levels`; if (s.lvFrac) return `+${s.lvFrac === 0.5 ? '½' : '⅓'} level · ${fmtNum(foodXP(k, p))} XP`; return `+${fmtNum(foodXP(k, p))} XP`; }
