function appIcon(k, tag) {
  const a = APPS[k];
  return `<${tag || 'div'} class="app-ic"${tag === 'button' ? ' type="button"' : ''} data-app="${k}"><i style="--c:${a[1]}"><svg viewBox="0 0 24 24" fill="none" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${a[2]}</svg></i><span>${a[0]}</span></${tag || 'div'}>`;
}
function priceHTML(p) {
  if (!p) return '<span class="price">Free</span>';
  if (p.p) return `<span class="price${st && st.pearls < p.p ? ' cant' : ''}">${ICON.pearl}${p.p}</span>`;
  return `<span class="price${st && st.coins < p.c ? ' cant' : ''}">${ICON.coin}${p.c}</span>`;
}
